@Test
public void edmEnabledFunctions() throws EdmPrimitiveTypeException {
    // GetEmployeesCount
    final ODataInvokeRequest<ClientProperty> getEmployeesCountReq = edmClient.getInvokeRequestFactory().getBoundFunctionInvokeRequest(edmClient.newURIBuilder().appendSingletonSegment("Company").build(), new FullQualifiedName(("Microsoft.Test.OData.Services.ODataWCFService.GetEmployeesCount")), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Company"), false);
    final ClientProperty getEmployeesCountRes = getEmployeesCountReq.execute().getBody();
    assertNotNull(getEmployeesCountRes);
    assertTrue(getEmployeesCountRes.hasPrimitiveValue());
    // GetProductDetails
    final ClientPrimitiveValue count = edmClient.getObjectFactory().newPrimitiveValueBuilder().buildInt32(1);
    final ODataInvokeRequest<ClientEntitySet> getProductDetailsReq = edmClient.getInvokeRequestFactory().getBoundFunctionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Products").appendKeySegment(5).build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.GetProductDetails"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Product"), false, Collections.<String, ClientValue>singletonMap("count", count));
    final ClientEntitySet getProductDetailsRes = getProductDetailsReq.execute().getBody();
    assertNotNull(getProductDetailsRes);
    assertEquals(1, getProductDetailsRes.getEntities().size());
    // GetRelatedProduct
    final Map<String, Object> keyMap = new LinkedHashMap<String, Object>();
    keyMap.put("ProductID", 6);
    keyMap.put("ProductDetailID", 1);
    URIBuilder builder = edmClient.newURIBuilder().appendEntitySetSegment("ProductDetails").appendKeySegment(keyMap);
    final ODataInvokeRequest<ClientEntity> getRelatedProductReq = edmClient.getInvokeRequestFactory().getBoundFunctionInvokeRequest(builder.build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.GetRelatedProduct"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.ProductDetail"), false);
    final ClientEntity getRelatedProductRes = getRelatedProductReq.execute().getBody();
    assertNotNull(getRelatedProductRes);
    assertEquals("Microsoft.Test.OData.Services.ODataWCFService.Product", getRelatedProductRes.getTypeName().toString());
    assertEquals(6, getRelatedProductRes.getProperty("ProductID").getPrimitiveValue().toCastValue(Integer.class), 0);
    // GetDefaultPI
    final ODataInvokeRequest<ClientEntity> getDefaultPIReq = edmClient.getInvokeRequestFactory().getBoundFunctionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Accounts").appendKeySegment(102).build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.GetDefaultPI"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Account"), false);
    final ClientEntity getDefaultPIRes = getDefaultPIReq.execute().getBody();
    assertNotNull(getDefaultPIRes);
    assertEquals("Microsoft.Test.OData.Services.ODataWCFService.PaymentInstrument", getDefaultPIRes.getTypeName().toString());
    assertEquals(102901, getDefaultPIRes.getProperty("PaymentInstrumentID").getPrimitiveValue().toCastValue(Integer.class), 0);
    // GetAccountInfo
    final ODataInvokeRequest<ClientProperty> getAccountInfoReq = edmClient.getInvokeRequestFactory().getBoundFunctionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Accounts").appendKeySegment(102).build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.GetAccountInfo"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Account"), false);
    final ClientProperty getAccountInfoRes = getAccountInfoReq.execute().getBody();
    assertNotNull(getAccountInfoRes);
    assertTrue(getAccountInfoRes.hasComplexValue());
    assertEquals("Microsoft.Test.OData.Services.ODataWCFService.AccountInfo", getAccountInfoRes.getComplexValue().getTypeName());
    // GetActualAmount
    final ClientPrimitiveValue bonusRate = edmClient.getObjectFactory().newPrimitiveValueBuilder().buildDouble(1.1);
    final ODataInvokeRequest<ClientProperty> getActualAmountReq = edmClient.getInvokeRequestFactory().getBoundFunctionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Accounts").appendKeySegment(102).appendNavigationSegment("MyGiftCard").build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.GetActualAmount"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.GiftCard"), false, Collections.<String, ClientValue>singletonMap("bonusRate", bonusRate));
    final ClientProperty getActualAmountRes = getActualAmountReq.execute().getBody();
    assertNotNull(getActualAmountRes);
    assertEquals(41.79, getActualAmountRes.getPrimitiveValue().toCastValue(Double.class), 0);
}

