@Test
public void edmEnabledActions() throws EdmPrimitiveTypeException {
    // IncreaseRevenue
    final ClientPrimitiveValue increaseValue = edmClient.getObjectFactory().newPrimitiveValueBuilder().buildInt64(12L);
    final ODataInvokeRequest<ClientProperty> increaseRevenueReq = edmClient.getInvokeRequestFactory().getBoundActionInvokeRequest(edmClient.newURIBuilder().appendSingletonSegment("Company").build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.IncreaseRevenue"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Company"), false, Collections.<String, ClientValue>singletonMap("IncreaseValue", increaseValue));
    final ClientProperty increaseRevenueRes = increaseRevenueReq.execute().getBody();
    assertNotNull(increaseRevenueRes);
    assertTrue(increaseRevenueRes.hasPrimitiveValue());
    // AddAccessRight
    final ClientEnumValue accessRight = edmClient.getObjectFactory().newEnumValue("Microsoft.Test.OData.Services.ODataWCFService.AccessLevel", "Execute");
    final ODataInvokeRequest<ClientProperty> getProductDetailsReq = edmClient.getInvokeRequestFactory().getBoundActionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Products").appendKeySegment(5).build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.AddAccessRight"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Product"), false, Collections.<String, ClientValue>singletonMap("accessRight", accessRight));
    getProductDetailsReq.setFormat(ContentType.JSON_FULL_METADATA);
    final ClientProperty getProductDetailsRes = getProductDetailsReq.execute().getBody();
    assertNotNull(getProductDetailsRes);
    assertTrue(getProductDetailsRes.hasEnumValue());
    // ResetAddress
    final ClientCollectionValue<ClientValue> addresses = edmClient.getObjectFactory().newCollectionValue("Collection(Microsoft.Test.OData.Services.ODataWCFService.Address)");
    final ClientComplexValue address = edmClient.getObjectFactory().newComplexValue("Microsoft.Test.OData.Services.ODataWCFService.Address");
    address.add(edmClient.getObjectFactory().newPrimitiveProperty("Street", edmClient.getObjectFactory().newPrimitiveValueBuilder().buildString("Piazza La Bomba E Scappa")));
    address.add(edmClient.getObjectFactory().newPrimitiveProperty("City", edmClient.getObjectFactory().newPrimitiveValueBuilder().buildString("Tollo")));
    address.add(edmClient.getObjectFactory().newPrimitiveProperty("PostalCode", edmClient.getObjectFactory().newPrimitiveValueBuilder().buildString("66010")));
    addresses.add(address);
    final ClientPrimitiveValue index = edmClient.getObjectFactory().newPrimitiveValueBuilder().buildInt32(0);
    final Map<String, ClientValue> params = new LinkedHashMap<String, ClientValue>(2);
    params.put("addresses", addresses);
    params.put("index", index);
    final Map<String, Object> keys = new HashMap<String, Object>();
    keys.put("PersonID", 2);
    final ODataInvokeRequest<ClientEntity> resetAddressReq = edmClient.getInvokeRequestFactory().getBoundActionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Customers").appendKeySegment(keys).build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.ResetAddress"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Person"), false, params);
    final ClientEntity resetAddressRes = resetAddressReq.execute().getBody();
    assertNotNull(resetAddressRes);
    assertEquals(2, resetAddressRes.getProperty("PersonID").getPrimitiveValue().toCastValue(Integer.class), 0);
    // RefreshDefaultPI
    Calendar dateTime = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
    dateTime.set(2014, 3, 9, 0, 0, 0);
    final ClientPrimitiveValue newDate = edmClient.getObjectFactory().newPrimitiveValueBuilder().setType(EdmPrimitiveTypeKind.DateTimeOffset).setValue(dateTime).build();
    final ODataInvokeRequest<ClientEntity> getDefaultPIReq = edmClient.getInvokeRequestFactory().getBoundActionInvokeRequest(edmClient.newURIBuilder().appendEntitySetSegment("Accounts").appendKeySegment(102).build(), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.RefreshDefaultPI"), new FullQualifiedName("Microsoft.Test.OData.Services.ODataWCFService.Account"), false, Collections.<String, ClientValue>singletonMap("newDate", newDate));
    final ClientEntity getDefaultPIRes = getDefaultPIReq.execute().getBody();
    assertNotNull(getDefaultPIRes);
    assertEquals("Microsoft.Test.OData.Services.ODataWCFService.PaymentInstrument", getDefaultPIRes.getTypeName().toString());
    assertEquals(102901, getDefaultPIRes.getProperty("PaymentInstrumentID").getPrimitiveValue().toCastValue(Integer.class), 0);
}

