@Test
public void updateBinding() throws Exception {
    // The entity MUST NOT contain related entities as inline content. It MAY contain binding information
    // for navigation properties. For single-valued navigation properties this replaces the relationship.
    // For collection-valued navigation properties this adds to the relationship.
    final URI entityURI = getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_KEY_NAV).appendKeySegment(1).build();
    // ESKeyNav(1).NavPropertyETKeyNavOne = ESKeyNav(2)
    // ESKeyNav(1).NavPropertyETKeyNavMany = { ESKeyNav(1), ESKeyNav(2) }
    // => Replace NavPropertyETKeyNavOne with ESKeyNav(3)
    // => Add to NavPropertyETKeyNavOne ESKeyNav(3)
    final ClientEntity entity = getFactory().newEntity(ET_KEY_NAV);
    final ClientLink navLinkOne = getFactory().newEntityNavigationLink(NAV_PROPERTY_ET_KEY_NAV_ONE, getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_KEY_NAV).appendKeySegment(3).build());
    final ClientLink navLinkMany = getFactory().newEntitySetNavigationLink(NAV_PROPERTY_ET_KEY_NAV_MANY, getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_KEY_NAV).appendKeySegment(3).build());
    entity.addLink(navLinkOne);
    entity.addLink(navLinkMany);
    final EdmEnabledODataClient edmEnabledClient = getEdmEnabledClient();
    final ODataEntityUpdateResponse<ClientEntity> updateResponse = edmEnabledClient.getCUDRequestFactory().getEntityUpdateRequest(entityURI, UpdateType.PATCH, entity).execute();
    final String cookie = updateResponse.getHeader(HttpHeader.SET_COOKIE).iterator().next();
    // Check if update was successful
    final URI entityGetURI = getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_KEY_NAV).appendKeySegment(1).expand(NAV_PROPERTY_ET_KEY_NAV_ONE, NAV_PROPERTY_ET_KEY_NAV_MANY).build();
    final ODataEntityRequest<ClientEntity> entityRequest = edmEnabledClient.getRetrieveRequestFactory().getEntityRequest(entityGetURI);
    entityRequest.addCustomHeader(HttpHeader.COOKIE, cookie);
    final ODataRetrieveResponse<ClientEntity> entityResponse = entityRequest.execute();
    assertShortOrInt(3, entityResponse.getBody().getNavigationLink(NAV_PROPERTY_ET_KEY_NAV_ONE).asInlineEntity().getEntity().getProperty(PROPERTY_INT16).getPrimitiveValue().toCastValue(Short.class));
    assertEquals(3, entityResponse.getBody().getNavigationLink(NAV_PROPERTY_ET_KEY_NAV_MANY).asInlineEntitySet().getEntitySet().getEntities().size());
    Iterator<ClientEntity> iterator = entityResponse.getBody().getNavigationLink(NAV_PROPERTY_ET_KEY_NAV_MANY).asInlineEntitySet().getEntitySet().getEntities().iterator();
    assertEquals(Short.valueOf((short) 1), iterator.next().getProperty(PROPERTY_INT16).getPrimitiveValue().toCastValue(Short.class));
    assertEquals(Short.valueOf((short) 2), iterator.next().getProperty(PROPERTY_INT16).getPrimitiveValue().toCastValue(Short.class));
    assertEquals(Short.valueOf((short) 3), iterator.next().getProperty(PROPERTY_INT16).getPrimitiveValue().toCastValue(Short.class));
}

