@Test
public void numericPromotion() {
    /*
     * The idea is use the largest possible number of a specific type and add a another number to force an
     * implicit conversion to an higher type
     */
    ODataRetrieveResponse<ClientEntitySet> response;
    // SByte => Int16
    // 2 ^ 7 -1 = 127
    byte byteValue = Byte.MAX_VALUE;
    response = sendRequest(ES_ALL_PRIM, "PropertyInt32 eq " + byteValue + " add " + 1);
    // No error occurs
    assertEquals(0, response.getBody().getEntities().size());
    // Int16 => Int32
    short shortValue = Short.MAX_VALUE;
    response = sendRequest(ES_ALL_PRIM, "PropertyInt32 eq " + shortValue + " add " + 1);
    // No error occurs
    assertEquals(0, response.getBody().getEntities().size());
    // Int32 => Int64
    int intValue = Integer.MAX_VALUE;
    response = sendRequest(ES_ALL_PRIM, "PropertyInt32 eq " + intValue + " add " + 1);
    // No error occurs
    assertEquals(0, response.getBody().getEntities().size());
    // Int64 => Double
    Long longValue = Long.MAX_VALUE;
    response = sendRequest(ES_ALL_PRIM, "PropertyInt32 eq " + longValue + " add " + 1);
    // No error occurs
    assertEquals(0, response.getBody().getEntities().size());
    // Single => Double
    Float floatValue = Float.MAX_VALUE;
    response = sendRequest(ES_ALL_PRIM, "PropertyInt32 eq " + floatValue.toString() + " add " + 1.0);
    // No error occurs
    assertEquals(0, response.getBody().getEntities().size());
}

@Test
public void nullComplexProperty() {
    // Create a new entry.The complex property PropertyCompComp is set to null. So the structure of the property
    // is still there, but filled is null values (primitive types)
    // We define a filter, which returns all entry where PropertyCompComp/PropertyComp/PropertyInt16 is equals to 1
    ClientEntity newEntity = getFactory().newEntity(new FullQualifiedName(SERVICE_NAMESPACE, "ETKeyNav"));
    newEntity.getProperties().add(getFactory().newComplexProperty("PropertyCompCompNav", null));
    newEntity.getProperties().add(getFactory().newPrimitiveProperty("PropertyInt16", getFactory().newPrimitiveValueBuilder().buildInt16((short) 4)));
    newEntity.getProperties().add(getFactory().newPrimitiveProperty("PropertyString", getFactory().newPrimitiveValueBuilder().buildString("Test")));
    newEntity.getProperties().add(getFactory().newComplexProperty("PropertyCompAllPrim", getFactory().newComplexValue(SERVICE_NAMESPACE + "." + "CTAllPrim").add(getFactory().newPrimitiveProperty("PropertyString", getFactory().newPrimitiveValueBuilder().buildString("Test 3")))));
    newEntity.getProperties().add(getFactory().newComplexProperty("PropertyCompTwoPrim", getFactory().newComplexValue(SERVICE_NAMESPACE + "." + "CTTwoPrim").add(getFactory().newPrimitiveProperty("PropertyInt16", getFactory().newPrimitiveValueBuilder().buildInt16((short) 1))).add(getFactory().newPrimitiveProperty("PropertyString", getFactory().newPrimitiveValueBuilder().buildString("Test2")))));
    newEntity.addLink(getFactory().newEntityNavigationLink("NavPropertyETTwoKeyNavOne", getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_TWO_KEY_NAV).appendKeySegment(new LinkedHashMap<String, Object>() {

        private static final long serialVersionUID = 1L;

        {
            put("PropertyInt16", 1);
            put("PropertyString", "1");
        }
    }).build()));
    final URI uri = getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment("ESKeyNav").build();
    ODataEntityCreateRequest<ClientEntity> request = getClient().getCUDRequestFactory().getEntityCreateRequest(uri, newEntity);
    ODataEntityCreateResponse<ClientEntity> response = request.execute();
    assertEquals(HttpStatusCode.CREATED.getStatusCode(), response.getStatusCode());
    final String cookie = response.getHeader(HttpHeader.SET_COOKIE).iterator().next();
    // Do the filter request
    ODataRetrieveResponse<ClientEntitySet> result = sendRequest("ESKeyNav", "PropertyCompCompNav/PropertyCompNav/PropertyInt16 eq 1", cookie);
    assertEquals(3, result.getBody().getEntities().size());
    // Try filter all entries where PropertyCompComp is null
    result = sendRequest("ESKeyNav", "PropertyCompCompNav/PropertyCompNav/PropertyInt16 eq null", cookie);
    assertEquals(1, result.getBody().getEntities().size());
}

