@Test
public void searchAndFilterWithTopSkipOrderByAndServerSidePaging() {
    ODataEntitySetRequest<ClientEntitySet> request = getClient().getRetrieveRequestFactory().getEntitySetRequest(getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_SERVER_SIDE_PAGING).search(// 1, 2, ..., 105, 107, ...
    "\"Number:\" AND NOT \"106\"").filter(// 1, 2, ..., 105
    "PropertyInt16 le 106").orderBy(// 105, 104, ..., 2, 1
    "PropertyInt16 desc").count(// 105
    true).skip(// 102, 101, ..., 2, 1
    3).top(// 102, 101, ...., 59
    43).build());
    setCookieHeader(request);
    ODataRetrieveResponse<ClientEntitySet> response = request.execute();
    saveCookieHeader(response);
    assertEquals(Integer.valueOf(105), response.getBody().getCount());
    assertEquals(10, response.getBody().getEntities().size());
    int id = 102;
    // Check first 10 entities.
    for (int i = 0; i < 10; i++) {
        ClientEntity entity = response.getBody().getEntities().get(i);
        assertShortOrInt(id, entity.getProperty(PROPERTY_INT16).getPrimitiveValue().toValue());
        id--;
    }
    // Get 3 * 10 = 30 Entities and check the key.
    for (int j = 0; j < 3; j++) {
        request = getClient().getRetrieveRequestFactory().getEntitySetRequest(response.getBody().getNext());
        setCookieHeader(request);
        response = request.execute();
        saveCookieHeader(response);
        assertEquals(Integer.valueOf(105), response.getBody().getCount());
        assertEquals(10, response.getBody().getEntities().size());
        for (int i = 0; i < 10; i++) {
            ClientEntity entity = response.getBody().getEntities().get(i);
            assertShortOrInt(id, entity.getProperty(PROPERTY_INT16).getPrimitiveValue().toValue());
            id--;
        }
    }
    // Get the last 3 items.
    request = getClient().getRetrieveRequestFactory().getEntitySetRequest(response.getBody().getNext());
    setCookieHeader(request);
    response = request.execute();
    saveCookieHeader(response);
    assertEquals(Integer.valueOf(105), response.getBody().getCount());
    assertEquals(3, response.getBody().getEntities().size());
    for (int i = 0; i < 3; i++) {
        ClientEntity entity = response.getBody().getEntities().get(i);
        assertShortOrInt(id, entity.getProperty(PROPERTY_INT16).getPrimitiveValue().toValue());
        id--;
    }
    // Make sure that the body no not contain a next link
    assertNull(response.getBody().getNext());
}

@Test
public void nextLinkFormat() {
    ODataEntitySetRequest<ClientEntitySet> request = getClient().getRetrieveRequestFactory().getEntitySetRequest(getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_SERVER_SIDE_PAGING).build());
