@Test
public void nextLinkFormatWithQueryOptions() {
    ODataEntitySetRequest<ClientEntitySet> request = getClient().getRetrieveRequestFactory().getEntitySetRequest(getClient().newURIBuilder(SERVICE_URI).appendEntitySetSegment(ES_SERVER_SIDE_PAGING).count(true).build());
    setCookieHeader(request);
    ODataRetrieveResponse<ClientEntitySet> response = request.execute();
    saveCookieHeader(response);
    // Check initial next link format
    URI nextLink = response.getBody().getNext();
    assertEquals(SERVICE_URI + "ESServerSidePaging?%24count=true&%24skiptoken=1%2A10", nextLink.toASCIIString());
    int token = 1;
    while (nextLink != null) {
        token++;
        // Check subsequent next links.
        request = getClient().getRetrieveRequestFactory().getEntitySetRequest(nextLink);
        setCookieHeader(request);
        response = request.execute();
        saveCookieHeader(response);
        nextLink = response.getBody().getNext();
        if (nextLink != null) {
            assertEquals(SERVICE_URI + "ESServerSidePaging?%24count=true&%24skiptoken=" + token + "%2A10", nextLink.toASCIIString());
        }
    }
    assertEquals(50 + 1, token);
}

