@Test
public void boundActionReturningDerivedTypeWithTypeCastSegInAction() throws Exception {
    URIBuilder builder = client.newURIBuilder(SERVICE_URI).appendEntitySetSegment("ESBase").appendKeySegment(111).appendDerivedEntityTypeSegment("olingo.odata.test1.ETTwoBase").appendActionCallSegment("olingo.odata.test1.BAETBaseETTwoBaseRTETTwoBase");
    Map<String, ClientValue> parameters = new HashMap<String, ClientValue>();
    final ClientPrimitiveValue propStrValue = client.getObjectFactory().newPrimitiveValueBuilder().buildString("NewStrValue");
    parameters.put("PropertyString", propStrValue);
    final ClientPrimitiveValue addPropStr1 = client.getObjectFactory().newPrimitiveValueBuilder().buildString("AddStrProp_5");
    parameters.put("AdditionalPropertyString_5", addPropStr1);
    final ClientPrimitiveValue addPropStr2 = client.getObjectFactory().newPrimitiveValueBuilder().buildString("AddStrProp_6");
    parameters.put("AdditionalPropertyString_6", addPropStr2);
    final ODataInvokeRequest<ClientEntity> req = client.getInvokeRequestFactory().getActionInvokeRequest(builder.build(), ClientEntity.class, parameters);
    req.setFormat(ContentType.JSON_FULL_METADATA);
    req.setContentType(ContentType.APPLICATION_JSON.toContentTypeString() + ";odata.metadata=full");
    ClientEntity entity = req.execute().getBody();
    assertNotNull(entity);
    assertEquals(entity.getProperties().size(), 4);
    assertEquals(entity.getTypeName().getFullQualifiedNameAsString(), "olingo.odata.test1.ETTwoBase");
}

