    // 2. Complex
    final EdmComplexType responseStatus = edm.getComplexType(new FullQualifiedName("Microsoft.Exchange.Services.OData.Model", "ResponseStatus"));
    assertNotNull(responseStatus);
    assertTrue(responseStatus.getNavigationPropertyNames().isEmpty());
    assertEquals("Recipient", responseStatus.getBaseType().getName());
    assertEquals(EdmPrimitiveTypeFactory.getInstance(EdmPrimitiveTypeKind.DateTimeOffset), responseStatus.getProperty("Time").getType());
    // 3. Entity
    final EdmEntityType user = edm.getEntityType(new FullQualifiedName("Microsoft.Exchange.Services.OData.Model", "User"));
    assertNotNull(user);
    assertFalse(user.getPropertyNames().isEmpty());
    assertFalse(user.getNavigationPropertyNames().isEmpty());
    final EdmEntityType entity = edm.getEntityType(new FullQualifiedName("Microsoft.Exchange.Services.OData.Model", "Entity"));
    assertEquals(entity, user.getBaseType());
    assertFalse(entity.getPropertyNames().isEmpty());
    assertTrue(entity.getNavigationPropertyNames().isEmpty());
    final EdmEntityType folder = edm.getEntityType(new FullQualifiedName("Microsoft.Exchange.Services.OData.Model", "Folder"));
    assertEquals(folder, user.getNavigationProperty("Inbox").getType());
    // 4. Action
    final EdmAction move = edm.getBoundAction(new FullQualifiedName("Microsoft.Exchange.Services.OData.Model", "Move"), new FullQualifiedName("Microsoft.Exchange.Services.OData.Model", "Folder"), false);
    assertNotNull(move);
    assertTrue(move.isBound());
    assertEquals(2, move.getParameterNames().size());
