@Test
public void methodsForIndividualRequests() throws Exception {
    final String batch = "--" + BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.POST + " ESAllPrim" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": " + APPLICATION_JSON + CRLF + CRLF + "{ \"PropertyString\": \"Foo\" }" + CRLF + "--" + BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.DELETE + " ESAllPrim(32767)" + HTTP_VERSION + CRLF + CRLF + CRLF + "--" + BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.PATCH + " ESAllPrim(32767)" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": " + APPLICATION_JSON + CRLF + CRLF + "{ \"PropertyString\": \"Foo\" }" + CRLF + "--" + BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.PUT + " ESAllPrim(32767)" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": " + APPLICATION_JSON + CRLF + CRLF + "{ \"PropertyString\": \"Foo\" }" + CRLF + "--" + BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.GET + " ESAllPrim(32767)" + HTTP_VERSION + CRLF + ACCEPT_HEADER + CRLF + CRLF + "--" + BOUNDARY + "--";
    final List<BatchRequestPart> requests = parse(batch);
    Assert.assertEquals(HttpMethod.POST, requests.get(0).getRequests().get(0).getMethod());
    Assert.assertEquals("/ESAllPrim", requests.get(0).getRequests().get(0).getRawODataPath());
    Assert.assertEquals("{ \"PropertyString\": \"Foo\" }", IOUtils.toString(requests.get(0).getRequests().get(0).getBody()));
    Assert.assertEquals(HttpMethod.DELETE, requests.get(1).getRequests().get(0).getMethod());
    Assert.assertEquals("/ESAllPrim(32767)", requests.get(1).getRequests().get(0).getRawODataPath());
    Assert.assertEquals(HttpMethod.PATCH, requests.get(2).getRequests().get(0).getMethod());
    Assert.assertEquals("/ESAllPrim(32767)", requests.get(2).getRequests().get(0).getRawODataPath());
    Assert.assertEquals("{ \"PropertyString\": \"Foo\" }", IOUtils.toString(requests.get(2).getRequests().get(0).getBody()));
    Assert.assertEquals(HttpMethod.PUT, requests.get(3).getRequests().get(0).getMethod());
    Assert.assertEquals("/ESAllPrim(32767)", requests.get(3).getRequests().get(0).getRawODataPath());
    Assert.assertEquals("{ \"PropertyString\": \"Foo\" }", IOUtils.toString(requests.get(3).getRequests().get(0).getBody()));
    Assert.assertEquals(HttpMethod.GET, requests.get(4).getRequests().get(0).getMethod());
    Assert.assertEquals("/ESAllPrim(32767)", requests.get(4).getRequests().get(0).getRawODataPath());
}

