@Test
public void contentId() throws Exception {
    final String batch = "--" + BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.GET + " ESAllPrim" + HTTP_VERSION + CRLF + ACCEPT_HEADER + HttpHeader.CONTENT_ID + ": BBB" + CRLF + CRLF + CRLF + "--" + BOUNDARY + CRLF + HttpHeader.CONTENT_TYPE + ": " + MULTIPART_MIXED + "; boundary=" + CHANGESET_BOUNDARY + CRLF + CRLF + "--" + CHANGESET_BOUNDARY + CRLF + MIME_HEADERS + HttpHeader.CONTENT_ID + ": 1" + CRLF + CRLF + HttpMethod.POST + " ESMedia" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": image/png" + CRLF + "Content-Transfer-Encoding: base64" + CRLF + CRLF + "iVBORw0KGgoAAAANSUhEUgAAABQAAAAMCAIAAADtbgqsAAAABmJLR0QA/wD/AP+gvaeTAAAAH0lE" + "QVQokWNgGHmA8S4FmpkosXngNDP+PzdANg+cZgBqiQK5mkdWWgAAAABJRU5ErkJggg==" + CRLF + CRLF + "--" + CHANGESET_BOUNDARY + CRLF + MIME_HEADERS + CRLF + HttpMethod.PUT + " $1/PropertyInt16" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": " + APPLICATION_JSON + CRLF + HttpHeader.CONTENT_ID + ": 2" + CRLF + CRLF + "{\"value\":5}" + CRLF + "--" + CHANGESET_BOUNDARY + "--" + CRLF + CRLF + "--" + BOUNDARY + "--";
    final List<BatchRequestPart> batchRequestParts = parse(batch);
    Assert.assertNotNull(batchRequestParts);
    for (BatchRequestPart multipart : batchRequestParts) {
        if (!multipart.isChangeSet()) {
            Assert.assertEquals(1, multipart.getRequests().size());
            Assert.assertEquals("BBB", multipart.getRequests().get(0).getHeader(HttpHeader.CONTENT_ID));
        } else {
            for (ODataRequest request : multipart.getRequests()) {
                if (HttpMethod.POST.equals(request.getMethod())) {
                    Assert.assertEquals("1", request.getHeader(HttpHeader.CONTENT_ID));
                } else if (HttpMethod.PUT.equals(request.getMethod())) {
                    Assert.assertEquals("2", request.getHeader(HttpHeader.CONTENT_ID));
                    Assert.assertEquals("/$1/PropertyInt16", request.getRawODataPath());
                    Assert.assertEquals(SERVICE_ROOT + "/$1/PropertyInt16", request.getRawRequestUri());
                }
            }
        }
    }
}

