@Test
public void epilog() throws Exception {
    String batch = "--" + BOUNDARY + CRLF + GET_REQUEST + "--" + BOUNDARY + CRLF + HttpHeader.CONTENT_TYPE + ": " + MULTIPART_MIXED + "; boundary=" + CHANGESET_BOUNDARY + CRLF + CRLF + "--" + CHANGESET_BOUNDARY + CRLF + MIME_HEADERS + HttpHeader.CONTENT_ID + ": 1" + CRLF + CRLF + HttpMethod.POST + " ESMedia" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": image/png" + CRLF + "Content-Transfer-Encoding: base64" + CRLF + CRLF + "iVBORw0KGgoAAAANSUhEUgAAABQAAAAMCAIAAADtbgqsAAAABmJLR0QA/wD/AP+gvaeTAAAAH0lE" + "QVQokWNgGHmA8S4FmpkosXngNDP+PzdANg+cZgBqiQK5mkdWWgAAAABJRU5ErkJggg==" + CRLF + CRLF + "--" + CHANGESET_BOUNDARY + CRLF + MIME_HEADERS + HttpHeader.CONTENT_ID + ": 2" + CRLF + CRLF + HttpMethod.PUT + " $1/PropertyInt16" + HTTP_VERSION + CRLF + HttpHeader.CONTENT_TYPE + ": " + APPLICATION_JSON + CRLF + CRLF + "{\"value\":5}" + CRLF + "--" + CHANGESET_BOUNDARY + "--" + CRLF + CRLF + "This is an epilog and must be ignored" + CRLF + CRLF + CRLF + "----1242" + CRLF + "--" + BOUNDARY + "--" + CRLF + "This is an epilog and must be ignored" + CRLF + CRLF + CRLF + "----1242";
    final List<BatchRequestPart> batchRequestParts = parse(batch);
    Assert.assertNotNull(batchRequestParts);
    Assert.assertEquals(2, batchRequestParts.size());
    BatchRequestPart getRequestPart = batchRequestParts.get(0);
    Assert.assertEquals(1, getRequestPart.getRequests().size());
    ODataRequest getRequest = getRequestPart.getRequests().get(0);
    Assert.assertEquals(HttpMethod.GET, getRequest.getMethod());
    BatchRequestPart changeSetPart = batchRequestParts.get(1);
    Assert.assertEquals(2, changeSetPart.getRequests().size());
    Assert.assertEquals("iVBORw0KGgoAAAANSUhEUgAAABQAAAAMCAIAAADtbgqsAAAABmJLR0QA/wD/AP+gvaeTAAAAH0lE" + "QVQokWNgGHmA8S4FmpkosXngNDP+PzdANg+cZgBqiQK5mkdWWgAAAABJRU5ErkJggg==" + CRLF, IOUtils.toString(changeSetPart.getRequests().get(0).getBody()));
    Assert.assertEquals("{\"value\":5}", IOUtils.toString(changeSetPart.getRequests().get(1).getBody()));
}

