@Test
public void testError() {
    EdmxReference reference = new EdmxReference(URI.create("../v4.0/cs02/vocabularies/Org.OData.Core.V1.xml"));
    reference.addInclude(new EdmxReferenceInclude("Org.OData.Core.V1", "Core"));
    ServiceHandler handler = new ProcessorServiceHandler();
    ServiceMetadata metadata = new ServiceMetadataImpl(provider, Collections.singletonList(reference), new ServiceMetadataETagSupport() {

        @Override
        public String getServiceDocumentETag() {
            return "W/\"serviceDocumentETag\"";
        }

        @Override
        public String getMetadataETag() {
            return "W/\"metadataETag\"";
        }
    });
    OData odata = new ODataImpl();
    ErrorHandler error = new ErrorHandler(odata, metadata, handler, ContentType.APPLICATION_ATOM_XML);
    assertNotNull(error);
    UriValidationException e = new UriValidationException("message", UriValidationException.MessageKeys.DOUBLE_KEY_PROPERTY, "param");
    ODataRequest request = new ODataRequest();
    ODataResponse response = new ODataResponse();
    error.handleException(e, request, response);
    error.handleException(new UriParserSemanticException("message", UriParserSemanticException.MessageKeys.COLLECTION_NOT_ALLOWED, "param"), request, response);
    error.handleException(new UriParserSyntaxException("message", UriParserSyntaxException.MessageKeys.DOUBLE_SYSTEM_QUERY_OPTION, "param"), request, response);
    String[] param = new String[2];
    error.handleException(new UriParserExceptionCustom("message", UriParserSyntaxException.MessageKeys.DOUBLE_SYSTEM_QUERY_OPTION, param), request, response);
    error.handleException(new BatchDeserializerException("message", BatchDeserializerException.MessageKeys.INVALID_BASE_URI, "param"), request, response);
    error.handleException(new SerializerException("message", SerializerException.MessageKeys.IO_EXCEPTION, "param"), request, response);
    error.handleException(new ContentNegotiatorException("message", ContentNegotiatorException.MessageKeys.NO_CONTENT_TYPE_SUPPORTED, "param"), request, response);
    error.handleException(new UriParserSyntaxException("message", UriParserSyntaxException.MessageKeys.DUPLICATED_ALIAS, "param"), request, response);
    error.handleException(new DeserializerException("message", DeserializerException.MessageKeys.DUPLICATE_PROPERTY, "param"), request, response);
    error.handleException(new ODataHandlerException("message", ODataHandlerException.MessageKeys.AMBIGUOUS_XHTTP_METHOD, "param"), request, response);
    error.handleException(new ODataApplicationException("message", 500, Locale.ENGLISH), request, response);
    error.handleException(new NullPointerException("message"), request, response);
    error.handleServerError(request, response, new ODataServerError());
}

