@Test
public void geoPoint() throws Exception {
    final EdmEntityType entityType = mockEntityType(EdmPrimitiveTypeKind.GeometryPoint);
    final String preamble = "{\"" + entityType.getPropertyNames().get(0) + "\":{";
    final Entity entity = deserialize(preamble + "\"type\":\"Point\",\"coordinates\":[1.25,2.75]," + "\"crs\":{\"type\":\"name\",\"properties\":{\"name\":\"EPSG:42\"}}}}", entityType);
    assertEquals(1, entity.getProperties().size());
    assertTrue(entity.getProperties().get(0).getValue() instanceof Point);
    final Point point = (Point) entity.getProperties().get(0).getValue();
    assertEquals(Geospatial.Dimension.GEOMETRY, point.getDimension());
    assertEquals("42", point.getSrid().toString());
    assertEquals(1.25, point.getX(), 0);
    assertEquals(2.75, point.getY(), 0);
    expectException(preamble + "}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":1}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"point\",\"coordinates\":null}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"LineString\"}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\"}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coord\":[]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.UNKNOWN_CONTENT);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":\"1 2\"}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":{\"x\":1,\"y\":2}}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[1]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[\"1\",2]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[1,\"2\"]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[1,2,\"3\"]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[1,2,3,4]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[12345678901234567,2]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException(preamble + "\"type\":\"Point\",\"coordinates\":[1,2],\"extra\":\"extra\"}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.UNKNOWN_CONTENT);
}

@Test
public void geoMultiPoint() throws Exception {
    final EdmEntityType entityType = mockEntityType(EdmPrimitiveTypeKind.GeographyMultiPoint);
    final Entity entity = deserialize("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"MultiPoint\",\"coordinates\":[[2.5,3.125,99],[3.5,4.125],[4.5,5.125]]}}", entityType);
    assertTrue(entity.getProperties().get(0).getValue() instanceof MultiPoint);
    final MultiPoint multiPoint = (MultiPoint) entity.getProperties().get(0).getValue();
    assertEquals(Geospatial.Dimension.GEOGRAPHY, multiPoint.getDimension());
    Iterator<Point> iterator = multiPoint.iterator();
    final Point point1 = iterator.next();
    assertEquals(Geospatial.Dimension.GEOGRAPHY, point1.getDimension());
    assertEquals(2.5, point1.getX(), 0);
    assertEquals(3.125, point1.getY(), 0);
    assertEquals(99, point1.getZ(), 0);
    final Point point2 = iterator.next();
    assertEquals(Geospatial.Dimension.GEOGRAPHY, point2.getDimension());
    assertEquals(3.5, point2.getX(), 0);
    assertEquals(4.125, point2.getY(), 0);
    final Point point3 = iterator.next();
    assertEquals(Geospatial.Dimension.GEOGRAPHY, point3.getDimension());
    assertEquals(4.5, point3.getX(), 0);
    assertEquals(5.125, point3.getY(), 0);
    assertFalse(iterator.hasNext());
    expectException("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"MultiPoint\",\"coordinates\":[{\"x\":1,\"y\":2}]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
}

@Test
public void geoLineString() throws Exception {
    final EdmEntityType entityType = mockEntityType(EdmPrimitiveTypeKind.GeometryLineString);
    final Entity entity = deserialize("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"LineString\",\"coordinates\":[[1.0,1.0],[2.0,2.0]]}}", entityType);
    assertTrue(entity.getProperties().get(0).getValue() instanceof LineString);
    final LineString lineString = (LineString) entity.getProperties().get(0).getValue();
    assertEquals(Geospatial.Dimension.GEOMETRY, lineString.getDimension());
    Iterator<Point> iterator = lineString.iterator();
    final Point point1 = iterator.next();
    assertEquals(Geospatial.Dimension.GEOMETRY, point1.getDimension());
    assertEquals(1, point1.getX(), 0);
    assertEquals(1, point1.getY(), 0);
    final Point point2 = iterator.next();
    assertEquals(Geospatial.Dimension.GEOMETRY, point2.getDimension());
    assertEquals(2, point2.getX(), 0);
    assertEquals(2, point2.getY(), 0);
    assertFalse(iterator.hasNext());
    expectException("{\"" + entityType.getPropertyNames().get(0) + "\":{\"type\":\"LineString\"}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    // A proper line string has at least two points but the OData specification has another opinion
    // so the following negative test would fail.
    //    expectException("{\"" + entityType.getPropertyNames().get(0)
    //        + "\":{\"type\":\"LineString\",\"coordinates\":[[1,2]]}}", entityType, ContentType.JSON,
    //        DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException("{\"" + entityType.getPropertyNames().get(0) + "\":{\"type\":\"LineString\",\"coordinates\":null}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
}

