@Test
public void geoPolygon() throws Exception {
    final EdmEntityType entityType = mockEntityType(EdmPrimitiveTypeKind.GeometryPolygon);
    Entity entity = deserialize("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"Polygon\",\"coordinates\":[[[0.0,0.0],[3.0,0.0],[3.0,3.0],[0.0,3.0],[0.0,0.0]]," + "[[1.0,1.0],[1.0,2.0],[2.0,2.0],[2.0,1.0],[1.0,1.0]]]}}", entityType);
    assertTrue(entity.getProperties().get(0).getValue() instanceof Polygon);
    Polygon polygon = (Polygon) entity.getProperties().get(0).getValue();
    assertEquals(Geospatial.Dimension.GEOMETRY, polygon.getDimension());
    assertEquals(0, polygon.getExterior().iterator().next().getX(), 0);
    assertEquals(1, polygon.getInterior(0).iterator().next().getY(), 0);
    entity = deserialize("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"Polygon\",\"coordinates\":[[[0,0],[3,0],[3,3],[0,3],[0,0]]]}}", entityType);
    polygon = (Polygon) entity.getProperties().get(0).getValue();
    assertEquals(0, polygon.getNumberOfInteriorRings());
    entity = deserialize("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"Polygon\",\"coordinates\":[[[0,0],[3,0],[3,3],[0,3],[0,0]]," + "[[1,1],[1,2],[2,2],[2,1],[1,1]]," + "[[1,1],[1,2],[2,2],[2,1],[1,1]]]}}", entityType);
    polygon = (Polygon) entity.getProperties().get(0).getValue();
    assertEquals(2, polygon.getNumberOfInteriorRings());
    expectException("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"Polygon\",\"coordinates\":{\"ext\":[[0,0],[3,0],[0,3],[0,0]]}}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"Polygon\",\"coordinates\":[[[0,0],[3,0],[3,3],[0,3]]]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
    expectException("{\"" + entityType.getPropertyNames().get(0) + "\":{" + "\"type\":\"Polygon\",\"coordinates\":[[[0,0],[3,0],[3,3],[0,3],[42,87]]]}}", entityType, ContentType.JSON, DeserializerException.MessageKeys.INVALID_VALUE_FOR_PROPERTY);
}

